@router.post(
    "/entries",
    status_code=status.HTTP_201_CREATED,
    dependencies=[Depends(_require_enabled)],
)
def create_entry(
    payload: EntryIn,
    _user: models.User = Depends(require_permission(EDIT_PERMISSION)),
